import pathlib,json,hashlib,base64,html,collections
R=pathlib.Path(__file__).resolve().parent;P=R/'parent'
def dump(n,x):(R/n).write_text(json.dumps(x,indent=2)+'\n',encoding='utf-8')
parent=json.loads((P/'review-results.json').read_text());audit=json.loads((R/'audit-results.json').read_text());visual={}
for p in sorted(R.glob('visual-*.json')):
 for x in json.loads(p.read_text())['reviews']:
  assert x['id'] not in visual
  assert len(x['inspected_paths'])==5
  visual[x['id']]={'report':p.name,'assessment':x}
assert set(visual)=={e['id'] for e in parent['entries']}
rows=[]
for e in parent['entries']:
 v=visual[e['id']];hold=e['visual_status']=='needs-decision' or v['assessment']['verdict']=='needs-user-review'
 s=next(x for x in audit['source_checks'] if x['id']==e['id'])
 missing=[x for x in e['remaining_gates'] if x not in ['independent-current-model-visual-review','independent QA-ART-08 review']]
 row={'id':e['id'],'verdict':'needs-user-review' if hold else 'candidate-with-limitations','art_changed':False,'final_approval':False,'launch_ready':False,'parent_verdict':e['visual_status'],'parent_visual_hold_preserved':e['visual_status']=='needs-decision','selection':e['selection'],'viewer':e['viewer'],'source_models':s['models'],'source_archives':s['archives'],'marketing':e['marketing'],'captures':e['captures'],'reviewed_image_hashes':e['reviewed_image_hashes'],'capture_base':'parent/','independent_visual':v,'parent_visual':{k:e[k] for k in ['quality','hardware','terrain','texture','limitations','decision']},'approval':e['approval'],'missing_gates':missing,'inherited_missing_gates':e['remaining_gates'],'fresh_checks':{'source_archive_crc_safe_paths_required_payloads':True,'source_and_delivered_viewer_hashes':True,'original_captures_and_marketing_inspected':True,'runtime':False,'motion':False,'blender_parity_collision':False,'fallback':False,'full_inner_archive_inventories':True},'historical_runtime':{'parent_commit':audit['parent_commit'],'browser':e['browser'],'motion':e['motion'],'extended':e['extended']},'critical_reproducible_failures':[]}
 if e['id']=='bosnia-and-herzegovina':
  row['lead_adjudication']='Retain additional independent visual decision hold: normal-view body and inner lid read ambiguously as wood versus hammered copper; promotional finish is stronger but also ambiguous. Lead comparison inspection confirms concern. This is material-identity uncertainty, not a proven wrong shader or broken geometry.'
  row['missing_gates'].append('copper-material-readability-user-decision')
 rows.append(row)
counts=dict(collections.Counter(x['verdict'] for x in rows));holds=[x['id'] for x in rows if x['verdict']=='needs-user-review']
ledger={'task':'t_22883167','parent_task':'t_33a49a6d','parent_commit':audit['parent_commit'],'scope':'Independent unchanged-candidate QA; original images and exact package bytes checked. No art approval or changes.','counts':counts,'needs_user_review':holds,'unreviewed_ids':[],'final_approvals':0,'launch_ready':False,'entries':rows,'limitations':['No fresh model runtime/motion, Blender reopen/parity/collision or fallback; parent runtime retained as historical. No changed art needing runtime rerun.','Static hinge contact is not certified; mobile captures are emulation, not physical-phone tests.','All final user approval, full source/browser acceptance, storage and release gates remain.']}
dump('reviewed-ledger.json',ledger)
parts=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>QA ART-08 independent review</title><style>body{margin:0;background:#15191b;color:#eee;font:16px system-ui}main{max-width:1050px;margin:auto;padding:20px}article{margin:24px 0;border-top:1px solid #777;padding-top:12px}img{width:100%;height:auto}p{line-height:1.5}code{overflow-wrap:anywhere}</style><main><h1>Batch 8 · Independent candidate review</h1><p>'+html.escape(json.dumps(counts))+' · 0 final approvals. No artwork changed.</p><p>Promotional illustrations compared with actual desktop/mobile model captures. Exact source/archive bytes freshly verified; model runtime and geometry evidence historical. Boards differ in framing, not calibrated material measurements.</p>']
for e in rows:
 parts.append('<article><h2>'+e['id']+' — '+e['verdict']+'</h2><img alt="Promotional and actual desktop/mobile comparison: '+e['id']+'" src="data:image/jpeg;base64,'+base64.b64encode((P/'boards'/(e['id']+'.jpg')).read_bytes()).decode()+'"><p>'+html.escape(e.get('lead_adjudication',e['parent_visual']['texture']))+'</p><p>Viewer '+str(e['viewer']['bytes'])+' bytes · <code>'+e['viewer']['sha256']+'</code></p></article>')
parts.append('<p>Next: preserve all five visual holds through collection consolidation; no launch approval.</p></main></html>');(R/'review.html').write_text(''.join(parts),encoding='utf-8')
(R/'.gitattributes').write_text('* -text\n')
(R/'README.md').write_text('# Independent QA ART-08\n\n'+json.dumps(counts)+'\n\nAll 25 assigned IDs and 125 original images independently reviewed. Four parent holds preserved; Bosnia and Herzegovina adds a copper/wood material-readability hold. Holds: '+', '.join(holds)+'. No art changes or final approvals.\n\nFresh exact selected viewer/GLB/editable source, 25 source ZIPs including 1,402 internal inventory records, 315 parent evidence records and three parent delivery archives verified. All viewers remain below 5,000,000 bytes. Historical USA source files are explicitly distinguished from selected v9 payloads.\n\nNo fresh model runtime, motion, Blender parity/collision or fallback checks; parent evidence is historical, not QA certification. Unchanged artwork requires no changed-art rerun. Review report opened offline on desktop/mobile separately.\n\nSmall report ZIP excludes full original captures and source ZIPs; exact parent commit/path/hash references preserve retrieval. Complete original capture copies are on this branch under parent/. Tooling requires Git objects, local original archives and Python; not a portable full art package.\n\nNext: downstream consolidation retains five visual holds and all final approval/storage/release gates. No production publication or release authorization.\n',encoding='utf-8')
print(counts,'holds',holds)
